#include <linux/cpu.h>
#include <linux/user_namespace.h>

int open_msr(struct inode *inode, struct file *file) {
    int cpu;

    /* Check if the caller has necessary permissions */
    if (!capable(CAP_SYS_RAWIO))
        return -EPERM;

    /* Retrieve and validate the CPU identifier from the file's path */
    cpu = smp_processor_id();
    if (cpu >= nr_cpu_ids || !cpu_online(cpu))
        return -ENXIO;

