int open_msr(struct inode *inode, struct file *file) {
    int cpu;
    int rc;

    /* Check if the caller has the necessary permissions */
    if (!capable(CAP_SYS_RAWIO)) {
        return -EPERM;
    }

    /* Retrieve the CPU identifier from the file's path */
    cpu = get_cpu_from_path(file);
    if (cpu < 0) {
        return -ENXIO;
    }

    /* Verify if the CPU is valid and online */
    if (!cpu_online(cpu)) {
        return -ENXIO;
    }

    /* Check if the CPU supports MSR operations */
    rc = check_msr_support(cpu);
    if (rc) {
        return -EIO;
    }

    return 0;
}

#include <linux/fs.h>
#include <linux/errno.h>
#include <linux/cpu.h>
#include <linux/slab.h>
#include <asm/msr.h>

int open_msr(struct inode *inode, struct file *file)
{
    int cpu;
    int rc = 0;

    if (!capable(CAP_SYS_RAWIO)) {
        return -EPERM;
    }

    cpu = smp_find_processor_id(minor(inode->i_rdev));
    if (cpu < 0) {
        return -ENXIO;
    }

    if (!cpu_online(cpu)) {
        return -ENXIO;
    }

    if (!boot_cpu_data.x86_msr) {
        return -EIO;
    }

    file->private_data = (void *)cpu;

    return rc;
}

