int open_msr(struct inode *inode, struct file *file) {
    int cpu;

    if (!capable(CAP_SYS_RAWIO))
        return -EPERM;

    cpu = cpu_number_from_id((unsigned long)file->f_path.dentry->d_inode->i_private);
    if (cpu < 0 || !cpu_online(cpu))
        return -ENXIO;

    if (!msr_ops_supported())
        return -EIO;

    return 0;
}

#include <linux/fs.h>
#include <linux/errno.h>
#include <linux/cpu.h>
#include <linux/slab.h>
#include <asm/msr.h>

int open_msr(struct inode *inode, struct file *file)
{
    int cpu;
    int rc;

    /* Check for raw I/O permission */
    if (!capable(CAP_SYS_RAWIO))
        return -EPERM;

    /* Extract the CPU number from the filename */
    cpu = smp_processor_id();
    if (cpu < 0 || cpu >= nr_cpu_ids)
        return -ENXIO;

    /* Check if CPU is online */
    if (!cpu_online(cpu))
        return -ENXIO;

    /* Check if MSR is supported */
    if (!boot_cpu_has(X86_FEATURE_MSR)) {
        return -EIO;
    }

    file->private_data = (void *)(long)cpu;
    return 0;
}
